'use client'
import { cn, getLinkComponent, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './header.module.css'

export interface HeaderLink {
  /** Stable React key. Provide when `href`/`label` may repeat (e.g. placeholder `#` links). */
  id?: string
  label: string
  href: string
  active?: boolean
}

export interface HeaderLabels {
  nav?: string
}

export interface HeaderProps extends HTMLAttributes<HTMLElement> {
  brand?: ReactNode
  links?: HeaderLink[]
  actions?: ReactNode
  /**
   * When true, the header sticks to the top on scroll.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  sticky?: boolean
  labels?: HeaderLabels
}

export function Header({
  brand,
  links,
  actions,
  sticky = false,
  labels,
  className,
  ...props
}: HeaderProps) {
  useSignals()
  const LinkComponent = getLinkComponent()
  const navLabel = labels?.nav ?? t(builtin.header.nav)
  return (
    <header
      role="banner"
      data-sticky={sticky || undefined}
      className={cn(styles['header'], className)}
      {...props}
    >
      {brand && <div className={styles['brand']}>{brand}</div>}
      {links && links.length > 0 && (
        <nav aria-label={navLabel} className={styles['nav']}>
          <ul className={styles['list']}>
            {links.map((link, i) => (
              <li key={link.id ?? `${i}-${link.href}`}>
                <LinkComponent
                  href={link.href}
                  aria-current={link.active ? 'page' : undefined}
                  data-state={link.active ? 'active' : undefined}
                  className={styles['link']}
                >
                  {link.label}
                </LinkComponent>
              </li>
            ))}
          </ul>
        </nav>
      )}
      <div className={styles['spacer']} />
      {actions && <div className={styles['actions']}>{actions}</div>}
    </header>
  )
}

@layer cascivo.component {
  .header {
    container: cascade-header / inline-size;
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-6);
    padding-inline: var(--cascivo-space-6);
    padding-block: var(--cascivo-space-3);
    font-family: var(--cascivo-font-sans);
    background-color: var(--cascivo-header-bg, var(--cascivo-color-surface));
    border-block-end: 1px solid var(--cascivo-color-border);

    &[data-sticky] {
      position: sticky;
      inset-block-start: 0;
      z-index: var(--cascivo-z-raised);
    }
  }

  .brand {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    font-size: var(--cascivo-text-base);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
    white-space: nowrap;

    & :any-link {
      color: inherit;
      text-decoration: none;
    }
  }

  .nav {
    min-inline-size: 0;
  }

  .list {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .link {
    display: inline-flex;
    align-items: center;
    padding-inline: var(--cascivo-space-3);
    padding-block: var(--cascivo-space-2);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-none);
    color: var(--cascivo-color-text-subtle);
    text-decoration: none;
    white-space: nowrap;
    border-radius: var(--cascivo-radius-item);
    transition:
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &[data-state='active'] {
      color: var(--cascivo-color-text);
      font-weight: var(--cascivo-font-medium);
      background-color: var(--cascivo-color-bg-subtle);
    }
  }

  .spacer {
    flex: 1;
  }

  .actions {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
  }

  /* Narrow container: tighter, smaller nav link labels */
  @container cascade-header (inline-size < 40rem) {
    .list {
      gap: 0;
    }

    .link {
      padding-inline: var(--cascivo-space-2);
      font-size: var(--cascivo-text-xs);
      letter-spacing: var(--cascivo-tracking-tight);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Header',
  description: 'App top bar with brand, primary navigation links, and an actions slot',
  category: 'navigation',
  // Markup is fully server-rendered; the only client-side work is re-resolving the
  // default label when the i18n locale or catalog changes, which is why the source
  // calls useSignals() and carries 'use client'. Nothing is unreachable with JS off.
  clientJs: 'enhancement',
  states: ['default'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'labels',
      type: 'HeaderLabels',
      required: false,
      description: 'Overrides for the component’s user-visible strings (i18n).',
    },
    {
      name: 'brand',
      type: 'React.ReactNode',
      required: false,
      description: 'Product name or logo area, typically wraps a link',
    },
    {
      name: 'links',
      type: '{ label: string; href: string; active?: boolean }[]',
      required: false,
      description: 'Primary navigation links; active link gets aria-current="page"',
    },
    {
      name: 'actions',
      type: 'React.ReactNode',
      required: false,
      description: 'Right-aligned slot for buttons or an avatar',
    },
    {
      name: 'sticky',
      description: 'When true, the header sticks to the top on scroll.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-header-bg',
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-color-bg-subtle',
    '--cascivo-focus-ring',
    '--cascivo-z-raised',
  ],
  accessibility: {
    role: 'banner',
    wcag: '2.2-AA',
    keyboard: ['Tab'],
  },
  examples: [
    {
      title: 'Basic',
      code: "<Header brand=\"cascivo\" links={[{ label: 'Docs', href: '/docs' }]} />",
    },
    {
      title: 'With actions',
      code: '<Header brand="cascivo" actions={<Button size="sm">Sign in</Button>} />',
    },
    {
      title: 'Sticky',
      code: '<Header sticky brand="cascivo" links={links} />',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['navigation', 'app-shell', 'top-bar', 'banner'],
  intent: {
    whenToUse: [
      'Providing a simple marketing or app top bar with brand, links, and actions',
      'Anchoring primary navigation across pages of a site',
      'Keeping the bar visible while scrolling (sticky)',
    ],
    whenNotToUse: [
      'Dense console apps with dropdown nav, global icon actions, and a hamburger — use ShellHeader',
      'Section headings within page content — use Heading',
    ],
    antiPatterns: [
      {
        bad: 'Building complex multi-menu console chrome on top of Header',
        good: '<ShellHeader> for console-grade navigation',
        why: 'Header is intentionally simple; console patterns belong to ShellHeader which provides them natively',
      },
    ],
    related: [
      {
        name: 'ShellHeader',
        relationship: 'alternative',
        reason: 'ShellHeader is the console-grade header with dropdowns and icon actions',
      },
    ],
    a11yRationale:
      'role="banner" marks the page header landmark; the active link is marked aria-current="page", and links/actions are real focusable controls so keyboard users can navigate the bar',
    flexibility: [
      {
        area: 'links and actions',
        level: 'flexible',
        note: 'Brand, links, and actions slots are optional and composable',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Surface, border, and z-index must resolve to --cascivo-* tokens',
      },
    ],
  },
}
